package org.rsmod.api.equipment.instance

/**
 * Display + roll catalog for equipment-instance unique effects (abilities).
 *
 * `spec-*` entries are OSRS weapon special attacks, `boss-*` entries are named boss mechanics, and
 * `pow-*` entries are empowered variants padding the pool. Abilities are metadata on the instance
 * today; `origin` records where the mechanic came from so combat wiring can be layered on later.
 *
 * Generated by work/port-tools/gen_ability_catalog.py — regenerate, do not hand-edit. The catalog
 * must contain exactly [SIZE] unique ids.
 */
public object EquipmentAbilityCatalog {
    public const val VERSION: Int = 1
    public const val SIZE: Int = 1000

