    private fun MutableList<Ability>.a(id: String, name: String, origin: String) {
        add(Ability(id, name, origin))
    }

    public val byId: Map<String, Ability> = all.associateBy(Ability::id)

    public val ids: List<String> = all.map(Ability::id)

    public fun displayName(id: String): String = byId[id]?.name ?: id

    init {
        require(all.size == SIZE) { "Ability catalog must contain exactly $SIZE entries." }
        require(byId.size == all.size) { "Ability ids must be unique." }
    }
}
